# Temporary source transport; excluded from the final product tree and history.
import base64, gzip, hashlib, json
from pathlib import Path

PACKED = ""
payload = gzip.decompress(base64.b64decode(PACKED))
assert hashlib.sha256(payload).hexdigest() == '4c949ffd11af185eec46e97a57c9aad522bf15fdda7b75fa4ecb9eae43351a3e'
files = json.loads(payload)
for name, content in files.items():
    path = Path(name)
    assert not path.is_absolute() and '..' not in path.parts
    assert name.startswith(('apps/server/src/services/taskDelivery/', 'packages/types/src/task/'))
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
index = Path('packages/types/src/task/index.ts')
export = "export * from './delivery';"
if export not in index.read_text():
    index.write_text(index.read_text() + '\n' + export + '\n')
Path('/tmp/delivery-paths.txt').write_text('\n'.join([*files, str(index)]) + '\n')
print('Applied', len(files), 'source files')
